constexpr Ability Impl<ABILITY_RAINBOW_SCALES> = {
    .onEntry = Impl<ABILITY_TASTE_THE_RAINBOW>.onEntry,
    .onDefensiveMultiplier = Impl<ABILITY_FIRE_SCALES>.onDefensiveMultiplier,
